@Override public Proxy find(final Host target){
  final String route;
  try {
    route = this.findNative(provider.get(target));
  } catch (IllegalArgumentException e) {
    log.warn(String.format("Invalid route configuration for target %s", target));
    return Proxy.DIRECT;
  }
  if (null == route) {
    try {
      if (log.isInfoEnabled()) {
        log.info(String.format("No proxy configuration found for target %s", target));
      }
    } catch (IllegalFormatException e) {
      log.warn("Invalid format in logging message");
    }
    return Proxy.DIRECT;
  }
  final URI proxy;
  try {
    proxy = URI.create(route);
  } catch (IllegalArgumentException e) {
    log.warn(String.format("Invalid URI format for route %s", route));
    return Proxy.DIRECT;
  }
  try {
    return new Proxy(Proxy.Type.valueOf(StringUtils.upperCase(proxy.getScheme())), proxy.getHost(), proxy.getPort());
  } catch (IllegalArgumentException e) {
    log.warn(String.format("Unsupported scheme for proxy %s", proxy));
  }
  return Proxy.DIRECT;
}
